<?php

namespace Classivo\Exams\Models;

use Classivo\Core\Concerns\BelongsToBranch;
use Classivo\Core\Concerns\BelongsToSession;
use Classivo\Core\Concerns\BelongsToTenant;
use Classivo\Core\Models\ClassSection;
use Classivo\Students\Models\Student;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Aggregated result per (exam, student): totals, percentage, grade, division, rank and
 * pass/fail. Generated by ExamResultService; `published` gates visibility to students.
 */
class ExamResult extends Model
{
    use BelongsToBranch, BelongsToSession, BelongsToTenant, SoftDeletes;

    public const RESULTS = ['pass' => 'Pass', 'fail' => 'Fail'];

    protected $fillable = [
        'school_id', 'branch_id', 'session_id', 'exam_id', 'student_id', 'class_id', 'section_id',
        'class_section_id', 'total_marks', 'total_full_marks', 'percentage', 'grade_id', 'division_id',
        'rank', 'result', 'published', 'published_at',
    ];

    protected function casts(): array
    {
        return [
            'total_marks' => 'decimal:2',
            'total_full_marks' => 'decimal:2',
            'percentage' => 'decimal:2',
            'rank' => 'integer',
            'published' => 'boolean',
            'published_at' => 'datetime',
        ];
    }

    public function exam(): BelongsTo
    {
        return $this->belongsTo(Exam::class);
    }

    public function student(): BelongsTo
    {
        return $this->belongsTo(Student::class);
    }

    public function classSection(): BelongsTo
    {
        return $this->belongsTo(ClassSection::class);
    }

    public function grade(): BelongsTo
    {
        return $this->belongsTo(Grade::class);
    }

    public function division(): BelongsTo
    {
        return $this->belongsTo(Division::class);
    }

    public function scopePublished(Builder $query): Builder
    {
        return $query->where('published', true);
    }
}
